import * as React from 'react';
import { Binding, BindingMode } from '@antimatterjs/react';
import { Checkbox as FluentCheckBox } from '@fluentui/react'
import { IToggleButtonProps, IToggleButtonState, ToggleButton } from './Primitives/ToggleButton';
import { Grid } from '@antimatterjs/positron/src/Controls/Grid';
import { HorizontalAlignment } from '@antimatterjs/positron/src/Enums';

export interface ICheckBoxProps extends IToggleButtonProps
{
    Label?: string | Binding
}

interface ICheckBoxState extends IToggleButtonState
{
    Label?: string,
}

export class CheckBox extends ToggleButton<ICheckBoxProps, ICheckBoxState>
{
    public static DefaultBindings = {
        IsEnabled: {
            FallbackValue: true
        },
        IsChecked: {
            Mode: BindingMode.TwoWay,
            FallbackValue: false
        },
        Label: {
            FallbackValue: '...'
        }
    };

    renderElement()
    {
        return (
            <FluentCheckBox
                styles={{
                    root: {
                        width: "fit-content"
                    }
                }}
                disabled={this.state.IsEnabled === undefined ? false : !this.state.IsEnabled}
                label={this.state.Label}
                checked={this.state.IsChecked}
                indeterminate={this.props.IsThreeState}
                onChange={(checked, newValue) =>
                    this.OnClick()}
            />
        );
    }
}